-- Historical schema generated by unchanged 0011 source migrations before enterprise upgrade; no business rows.
BEGIN TRANSACTION;
CREATE TABLE adapters (
	name VARCHAR(200) NOT NULL, 
	protocol VARCHAR(32) NOT NULL, 
	config JSON NOT NULL, 
	health JSON NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	provenance VARCHAR(24) NOT NULL, 
	source_registry JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO "alembic_version" VALUES('0011');
CREATE TABLE approvals (
	case_id VARCHAR(64) NOT NULL, 
	plan_id VARCHAR(64) NOT NULL, 
	actor_id VARCHAR(64) NOT NULL, 
	approved BOOLEAN NOT NULL, 
	reason TEXT NOT NULL, 
	fingerprint VARCHAR(64) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	UNIQUE (plan_id), 
	FOREIGN KEY(plan_id) REFERENCES plans (id)
);
CREATE TABLE audit (
	actor_id VARCHAR(100) NOT NULL, 
	action VARCHAR(100) NOT NULL, 
	target_id VARCHAR(100) NOT NULL, 
	request_id VARCHAR(120) NOT NULL, 
	detail JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE cases (
	title VARCHAR(200) NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	process VARCHAR(40) NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	version INTEGER NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	context JSON NOT NULL, 
	diagnosis JSON NOT NULL, 
	rounds INTEGER NOT NULL, 
	model_calls INTEGER NOT NULL, 
	outcome JSON NOT NULL, 
	review_flags JSON NOT NULL, 
	anomaly_key VARCHAR(120), 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE commands (
	"key" VARCHAR(120) NOT NULL, 
	actor_id VARCHAR(100) NOT NULL, 
	fingerprint VARCHAR(64) NOT NULL, 
	response JSON NOT NULL, 
	authorization_hash VARCHAR(64) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, actor_id, "key")
);
CREATE TABLE dispositions (
	object_id VARCHAR(120) NOT NULL, 
	route_id VARCHAR(64) NOT NULL, 
	case_id VARCHAR(64), 
	action VARCHAR(20) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	reviewer_id VARCHAR(64), 
	reason TEXT NOT NULL, 
	cycle INTEGER NOT NULL, 
	return_step_id VARCHAR(64), 
	version INTEGER NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(route_id) REFERENCES routes (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id)
);
CREATE TABLE distributions (
	target_node VARCHAR(100) NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	kind VARCHAR(30) NOT NULL, 
	record_id VARCHAR(64) NOT NULL, 
	action VARCHAR(20) NOT NULL, 
	generation INTEGER NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	package JSON NOT NULL, 
	result JSON NOT NULL, 
	expires_at DATETIME NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, target_node, kind, record_id, generation)
);
CREATE TABLE evidence (
	filename VARCHAR(200) NOT NULL, 
	object_key VARCHAR(500) NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	media_type VARCHAR(100) NOT NULL, 
	size INTEGER NOT NULL, 
	source VARCHAR(32) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	replication_status VARCHAR(24) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (object_key)
);
CREATE TABLE inbox (
	event_id VARCHAR(64) NOT NULL, 
	source_node VARCHAR(100) NOT NULL, 
	sequence INTEGER NOT NULL, 
	payload JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, source_node, event_id)
);
CREATE TABLE inspections (
	source_id VARCHAR(120) NOT NULL, 
	record_id VARCHAR(120) NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	object_id VARCHAR(120), 
	granularity VARCHAR(30) NOT NULL, 
	association VARCHAR(40) NOT NULL, 
	occurred_at DATETIME NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	provenance VARCHAR(24) NOT NULL, 
	result JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, source_id, record_id)
);
CREATE TABLE knowledge (
	category VARCHAR(30) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	content TEXT NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	revision INTEGER NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	reviewer_id VARCHAR(64), 
	scope JSON NOT NULL, 
	source JSON NOT NULL, 
	rules JSON NOT NULL, 
	previous_id VARCHAR(64), 
	valid_until DATETIME NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(previous_id) REFERENCES knowledge (id)
);
CREATE TABLE knowledge_vectors (
	knowledge_id VARCHAR(64) NOT NULL, 
	embedding VECTOR(384) NOT NULL, 
	model_version VARCHAR(100) NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (knowledge_id), 
	FOREIGN KEY(knowledge_id) REFERENCES knowledge (id)
);
CREATE TABLE lab_results (
	object_id VARCHAR(120) NOT NULL, 
	metric VARCHAR(100) NOT NULL, 
	method VARCHAR(200) NOT NULL, 
	value VARCHAR(100) NOT NULL, 
	unit VARCHAR(30) NOT NULL, 
	occurred_at DATETIME NOT NULL, 
	operator_id VARCHAR(64) NOT NULL, 
	evidence_ids JSON NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE learning_records (
	kind VARCHAR(30) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	version INTEGER NOT NULL, 
	revision INTEGER NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	reviewer_id VARCHAR(64), 
	case_id VARCHAR(64), 
	file_id VARCHAR(64), 
	previous_id VARCHAR(64), 
	knowledge_id VARCHAR(64), 
	payload JSON NOT NULL, 
	snapshot JSON NOT NULL, 
	activation JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(file_id) REFERENCES evidence (id), 
	FOREIGN KEY(previous_id) REFERENCES learning_records (id), 
	FOREIGN KEY(knowledge_id) REFERENCES knowledge (id)
);
CREATE TABLE learning_tasks (
	record_id VARCHAR(64) NOT NULL, 
	kind VARCHAR(30) NOT NULL, 
	actor_id VARCHAR(64) NOT NULL, 
	authorization_hash VARCHAR(64) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	attempts INTEGER NOT NULL, 
	lease_token VARCHAR(64) NOT NULL, 
	lease_until DATETIME, 
	next_at DATETIME NOT NULL, 
	data JSON NOT NULL, 
	result JSON NOT NULL, 
	error_code VARCHAR(100) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(record_id) REFERENCES learning_records (id)
);
CREATE TABLE masters (
	kind VARCHAR(40) NOT NULL, 
	code VARCHAR(120) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	parent_id VARCHAR(64), 
	data JSON NOT NULL, 
	version INTEGER NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, kind, code), 
	FOREIGN KEY(parent_id) REFERENCES masters (id)
);
CREATE TABLE measurements (
	source_id VARCHAR(100) NOT NULL, 
	record_id VARCHAR(120) NOT NULL, 
	equipment_id VARCHAR(120) NOT NULL, 
	metric VARCHAR(100) NOT NULL, 
	occurred_at DATETIME NOT NULL, 
	value DOUBLE NOT NULL, 
	unit VARCHAR(40) NOT NULL, 
	quality VARCHAR(40) NOT NULL, 
	value_type VARCHAR(16) NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, source_id, record_id, metric)
);
CREATE TABLE outbox (
	kind VARCHAR(100) NOT NULL, 
	payload JSON NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	attempts INTEGER NOT NULL, 
	next_at DATETIME NOT NULL, 
	last_error TEXT NOT NULL, 
	sequence INTEGER NOT NULL, 
	synced BOOLEAN NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE passages (
	object_id VARCHAR(120) NOT NULL, 
	granularity VARCHAR(30) NOT NULL, 
	route_id VARCHAR(64) NOT NULL, 
	step_id VARCHAR(64) NOT NULL, 
	sequence INTEGER NOT NULL, 
	entered_at DATETIME NOT NULL, 
	exited_at DATETIME NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, object_id, sequence)
);
CREATE TABLE plans (
	case_id VARCHAR(64) NOT NULL, 
	revision INTEGER NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	content JSON NOT NULL, 
	fingerprint VARCHAR(64) NOT NULL, 
	context_hash VARCHAR(64) NOT NULL, 
	expires_at DATETIME NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (case_id, revision), 
	FOREIGN KEY(case_id) REFERENCES cases (id)
);
CREATE TABLE raw_records (
	source_id VARCHAR(100) NOT NULL, 
	record_id VARCHAR(160) NOT NULL, 
	source_session_id VARCHAR(100) NOT NULL, 
	payload_hash VARCHAR(64) NOT NULL, 
	object_key VARCHAR(500) NOT NULL, 
	mapping_version VARCHAR(100) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	source_time DATETIME, 
	received_at DATETIME NOT NULL, 
	normalized_ids JSON NOT NULL, 
	errors JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, source_id, source_session_id, record_id, payload_hash), 
	UNIQUE (object_key)
);
CREATE TABLE receipts (
	case_id VARCHAR(64) NOT NULL, 
	plan_id VARCHAR(64) NOT NULL, 
	actor_id VARCHAR(64) NOT NULL, 
	content JSON NOT NULL, 
	effective_at DATETIME NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	UNIQUE (plan_id), 
	FOREIGN KEY(plan_id) REFERENCES plans (id)
);
CREATE TABLE remote_requests (
	author_id VARCHAR(64) NOT NULL, 
	target_node VARCHAR(100) NOT NULL, 
	kind VARCHAR(40) NOT NULL, 
	payload JSON NOT NULL, 
	expires_at DATETIME NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	result JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE retests (
	case_id VARCHAR(64) NOT NULL, 
	plan_id VARCHAR(64) NOT NULL, 
	actor_id VARCHAR(64) NOT NULL, 
	result JSON NOT NULL, 
	verdict VARCHAR(30) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id), 
	FOREIGN KEY(plan_id) REFERENCES plans (id)
);
CREATE TABLE routes (
	name VARCHAR(200) NOT NULL, 
	process VARCHAR(40) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	revision INTEGER NOT NULL, 
	steps JSON NOT NULL, 
	disposition JSON NOT NULL, 
	author_id VARCHAR(64) NOT NULL, 
	previous_id VARCHAR(64), 
	reviewer_id VARCHAR(64), 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(previous_id) REFERENCES routes (id)
);
CREATE TABLE runs (
	case_id VARCHAR(64) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(case_id) REFERENCES cases (id)
);
CREATE TABLE sessions (
	user_id VARCHAR(64) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	expires_at DATETIME NOT NULL, 
	auth_revision INTEGER NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	UNIQUE (token_hash)
);
CREATE TABLE sites (
	node_id VARCHAR(100) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	active BOOLEAN NOT NULL, 
	last_seen DATETIME, 
	sequence INTEGER NOT NULL, 
	acknowledged INTEGER NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (node_id)
);
CREATE TABLE snapshots (
	source_node VARCHAR(100) NOT NULL, 
	entity_id VARCHAR(64) NOT NULL, 
	version INTEGER NOT NULL, 
	data JSON NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, source_node, entity_id)
);
CREATE TABLE study_groups (
	dataset_id VARCHAR(64) NOT NULL, 
	group_key VARCHAR(160) NOT NULL, 
	split VARCHAR(30) NOT NULL, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, site_id, group_key), 
	FOREIGN KEY(dataset_id) REFERENCES learning_records (id)
);
CREATE TABLE users (
	username VARCHAR(120) NOT NULL, 
	password_hash TEXT NOT NULL, 
	role VARCHAR(32) NOT NULL, 
	allowed_sites JSON NOT NULL, 
	allowed_lines JSON NOT NULL, 
	active BOOLEAN NOT NULL, 
	auth_revision INTEGER NOT NULL, 
	auth_origin VARCHAR(30) NOT NULL, 
	center_revision INTEGER NOT NULL, 
	central_active BOOLEAN NOT NULL, 
	lease_expires_at DATETIME, 
	id VARCHAR(64) NOT NULL, 
	tenant_id VARCHAR(80) NOT NULL, 
	site_id VARCHAR(80) NOT NULL, 
	created_at DATETIME NOT NULL, 
	scope_line_id VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (tenant_id, username)
);
